const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper: Sentinel-2 SR cloud mask and NBR
function maskS2sr(img) {
  var qa = img.select('QA60');
  var mask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
  return img.updateMask(mask).divide(10000);
}
function addNBR_S2(img) {
  var nir = img.select('B8');
  var swir2 = img.select('B12');
  var nbr = nir.subtract(swir2).divide(nir.add(swir2)).rename('NBR');
  return img.addBands(nbr);
}

// Helper: Landsat 8/9 L2 cloud mask, scaling, and NBR
function prepL89(img) {
  var qa = img.select('QA_PIXEL');
  var radsat = img.select('QA_RADSAT');
  var cloudMask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
    .and(qa.bitwiseAnd(1 << 4).eq(0))         // Cloud shadow
    .and(qa.bitwiseAnd(1 << 5).eq(0))         // Snow
    .and(qa.bitwiseAnd(1 << 1).eq(0))         // Dilated cloud
    .and(qa.bitwiseAnd(1 << 2).eq(0));        // Cirrus
  cloudMask = cloudMask.and(radsat.eq(0));
  var scaled = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
                  .multiply(0.0000275).add(-0.2)
                  .updateMask(cloudMask);
  var withScaled = img.addBands(scaled, null, true);
  var nbr = withScaled.select('SR_B5').subtract(withScaled.select('SR_B7'))
                      .divide(withScaled.select('SR_B5').add(withScaled.select('SR_B7')))
                      .rename('NBR');
  return withScaled.addBands(nbr);
}

async function getCompositeMetrics(label, start, end, geom) {
  // Try Sentinel-2 first
  let usedSource = null;
  let usedStart = start, usedEnd = end;
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(start, end)
    .filterBounds(geom)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2sr)
    .map(addNBR_S2);
  let size = await col.size().getInfo();
  let meanCloud = size > 0 ? await col.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo() : null;

  let img = null;
  let validCount = 0;
  if (size > 0) {
    usedSource = 'S2';
    img = col.median().select('NBR');
    let countDict = await img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e13,
      tileScale: 4
    }).getInfo();
    validCount = (countDict && countDict.NBR) ? countDict.NBR : 0;
  }

  // If no S2 or no valid pixels, try Landsat 8/9
  if (size === 0 || validCount === 0) {
    let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');
    let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2');
    col = l8.merge(l9)
      .filterDate(start, end)
      .filterBounds(geom)
      .map(prepL89);
    size = await col.size().getInfo();
    meanCloud = null; // not directly comparable
    if (size > 0) {
      usedSource = 'L8/9';
      img = col.median().select('NBR');
      let countDict = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e13,
        tileScale: 4
      }).getInfo();
      validCount = (countDict && countDict.NBR) ? countDict.NBR : 0;
    }
  }

  // If still no images, widen window ±5 days and retry once (S2 then L8/9)
  if (!usedSource) {
    usedStart = ee.Date(start).advance(-5, 'day');
    usedEnd = ee.Date(end).advance(5, 'day');
    col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(usedStart, usedEnd)
      .filterBounds(geom)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
      .map(maskS2sr)
      .map(addNBR_S2);
    size = await col.size().getInfo();
    meanCloud = size > 0 ? await col.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE').getInfo() : null;
    if (size > 0) {
      usedSource = 'S2 (widened)';
      img = col.median().select('NBR');
      let countDict = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e13,
        tileScale: 4
      }).getInfo();
      validCount = (countDict && countDict.NBR) ? countDict.NBR : 0;
    } else {
      let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');
      let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2');
      col = l8.merge(l9)
        .filterDate(usedStart, usedEnd)
        .filterBounds(geom)
        .map(prepL89);
      size = await col.size().getInfo();
      meanCloud = null;
      if (size > 0) {
        usedSource = 'L8/9 (widened)';
        img = col.median().select('NBR');
        let countDict = await img.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geom,
          scale: 1000,
          maxPixels: 1e13,
          tileScale: 4
        }).getInfo();
        validCount = (countDict && countDict.NBR) ? countDict.NBR : 0;
      }
    }
  }

  // No images in any attempt
  if (!usedSource) {
    return { label, source: 'None', images: 0, meanCloud: null, validPixels: 0, areaKm2: null, status: 'C1' };
  }
  // Images exist but no valid pixels after masking
  if (!validCount || validCount === 0) {
    let imgCount = await col.size().getInfo();
    return { label, source: usedSource, images: imgCount, meanCloud, validPixels: 0, areaKm2: null, status: 'C2' };
  }

  // Compute burn area (NBR <= 0.1)
  let burnMask = img.lte(0.1);
  let areaImg = ee.Image.pixelArea().updateMask(burnMask).rename('area');
  let areaDict = await areaImg.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e13,
    tileScale: 4
  }).getInfo();
  let areaM2 = areaDict ? areaDict.area : null;
  if (areaM2 === null || areaM2 === undefined) {
    return { label, source: usedSource, images: await col.size().getInfo(), meanCloud, validPixels: validCount, areaKm2: null, status: 'C3' };
  }
  let areaKm2 = areaM2 / 1e6;
  if (!isFinite(areaKm2) || areaKm2 < 0 || areaKm2 > 10000) {
    return { label, source: usedSource, images: await col.size().getInfo(), meanCloud, validPixels: validCount, areaKm2: null, status: 'C3' };
  }

  return {
    label,
    source: usedSource,
    images: await col.size().getInfo(),
    meanCloud,
    validPixels: validCount,
    areaKm2,
    status: 'OK'
  };
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const pt = ee.Geometry.Point([-105.503, 35.759]);
    const region = pt.buffer(10000); // 10 km radius around Hermit Park
    const t1Start = ee.Date('2022-04-18'); const t1End = ee.Date('2022-04-20');
