      console.log('Reason: Empty Collection for at least one period.');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    if (res1.status === 'C2' || res2.status === 'C2') {
      console.log(`${res1.label} -> Source: ${res1.source}, Images: ${res1.images}, ValidPx: ${res1.validPixels}`);
      console.log(`${res2.label} -> Source: ${res2.source}, Images: ${res2.images}, ValidPx: ${res2.validPixels}`);
      console.log('Reason: No valid pixels after cloud masking for at least one period.');
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }
    if (res1.status === 'C3' || res2.status === 'C3') {
      console.log(`${res1.label} -> Source: ${res1.source}, Images: ${res1.images}, ValidPx: ${res1.validPixels}, Area(km2): ${res1.areaKm2}`);
      console.log(`${res2.label} -> Source: ${res2.source}, Images: ${res2.images}, ValidPx: ${res2.validPixels}, Area(km2): ${res2.areaKm2}`);
      console.log('Reason: Calculation failure (null/NaN/invalid).');
      console.log('C3: Calculation Failure (Result is None/NaN/invalid).');
      console.log('C3');
      return;
    }

    // 4. Calculation & 5. Validation & Final Answer
    const a1 = res1.areaKm2;
    const a2 = res2.areaKm2;
    const diff = a2 - a1;

    // Evidence lines (<=20 total)
    console.log(`${res1.label} -> Source: ${res1.source}, Images: ${res1.images}${res1.meanCloud !== null ? (`, MeanCloud%: ${res1.meanCloud.toFixed(1)}`) : ''}, ValidPx: ${res1.validPixels}, Burn(km2): ${a1.toFixed(2)}`);
    console.log(`${res2.label} -> Source: ${res2.source}, Images: ${res2.images}${res2.meanCloud !== null ? (`, MeanCloud%: ${res2.meanCloud.toFixed(1)}`) : ''}, ValidPx: ${res2.validPixels}, Burn(km2): ${a2.toFixed(2)}`);
    console.log(`Area change (T2 - T1) km2: ${diff.toFixed(2)}`);

    // Tolerance to avoid noise due to coarse scale
    const tol = 0.2; // km^2
    if (!isFinite(diff)) {
      console.log('C3: Calculation Failure (Result is None/NaN/invalid).');
      console.log('C3');
    } else if (diff > tol) {
      console.log('A: Yes');
      console.log('A: Yes'); // Final tag
    } else {
      console.log('B: No');
      console.log('B: No'); // Final tag
    }
  } catch (err) {
    console.error('Error:', err && err.message ? err.message : err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

